CREATE TYPE "curriculum_level" AS ENUM ('starters');
CREATE TYPE "curriculum_category" AS ENUM ('vocabulary', 'grammar', 'topic', 'language_target');
CREATE TYPE "curriculum_paper" AS ENUM ('listening', 'reading_writing');
CREATE TYPE "policy_input_kind" AS ENUM ('choice', 'boolean', 'yes_no', 'number', 'name', 'word', 'assignment');
CREATE TABLE "curriculum_targets" ("id" uuid PRIMARY KEY, "canonical_id" text NOT NULL, "category" "curriculum_category" NOT NULL, "level" "curriculum_level" NOT NULL DEFAULT 'starters', "guidance" text NOT NULL, "created_by" uuid NOT NULL REFERENCES "accounts"("id"), "created_at" timestamptz NOT NULL DEFAULT now(), CONSTRAINT "curriculum_targets_canonical_id_unique" UNIQUE("canonical_id"));
CREATE TABLE "curriculum_guidance" ("id" uuid PRIMARY KEY, "paper" "curriculum_paper" NOT NULL, "part" integer NOT NULL, "engine" text NOT NULL, "topic" text NOT NULL, "task_format" text NOT NULL, "max_words" integer NOT NULL, "max_options" integer NOT NULL, "approved_names" jsonb NOT NULL, "created_at" timestamptz NOT NULL DEFAULT now(), CONSTRAINT "curriculum_guidance_part_check" CHECK ("part" BETWEEN 1 AND 5), CONSTRAINT "curriculum_guidance_limits_check" CHECK ("max_words" > 0 AND "max_options" > 0), CONSTRAINT "curriculum_guidance_engine_unique" UNIQUE("engine"));
CREATE TABLE "answer_policies" ("id" uuid PRIMARY KEY, "canonical_id" text NOT NULL, "target_id" uuid NOT NULL REFERENCES "curriculum_targets"("id"), "current_version_id" uuid, "created_at" timestamptz NOT NULL DEFAULT now(), CONSTRAINT "answer_policies_canonical_id_unique" UNIQUE("canonical_id"));
CREATE TABLE "answer_policy_versions" ("id" uuid PRIMARY KEY, "policy_id" uuid NOT NULL REFERENCES "answer_policies"("id"), "version" integer NOT NULL, "input_kind" "policy_input_kind" NOT NULL, "canonical_answer" jsonb NOT NULL, "accepted_answers" jsonb NOT NULL, "normalisation" jsonb NOT NULL, "max_words" integer NOT NULL, "teacher_review_if_uncertain" text NOT NULL, "created_by" uuid NOT NULL REFERENCES "accounts"("id"), "created_at" timestamptz NOT NULL DEFAULT now(), CONSTRAINT "answer_policy_versions_policy_version_unique" UNIQUE("policy_id", "version"), CONSTRAINT "answer_policy_versions_max_words_check" CHECK ("max_words" > 0));
CREATE TABLE "policy_conformance_vectors" ("id" uuid PRIMARY KEY, "policy_version_id" uuid NOT NULL REFERENCES "answer_policy_versions"("id"), "response" jsonb NOT NULL, "expected_outcome" text NOT NULL, "created_at" timestamptz NOT NULL DEFAULT now(), CONSTRAINT "policy_conformance_vectors_outcome_check" CHECK ("expected_outcome" IN ('correct', 'incorrect', 'needs_teacher_review')));
CREATE INDEX "policy_conformance_vectors_version_idx" ON "policy_conformance_vectors" ("policy_version_id");
CREATE TABLE "curriculum_audit_events" ("id" uuid PRIMARY KEY, "actor_id" uuid NOT NULL REFERENCES "accounts"("id"), "action" text NOT NULL, "target_id" uuid NOT NULL, "created_at" timestamptz NOT NULL DEFAULT now());
CREATE INDEX "curriculum_audit_events_target_idx" ON "curriculum_audit_events" ("target_id");
